class Solution:
    def sumOfNumberAndReverse(self, num: int) -> bool:
        def rev(n):
            r = 0
            while n:
                r = r * 10 + n % 10
                n //= 10
            return r
        for x in range(num + 1):
            if x + rev(x) == num:
                return True
        return False

