class Solution {
public:
    bool sumOfNumberAndReverse(int num) {
        auto rev = [](int n) {
            long long r = 0;
            while (n) { r = r * 10 + n % 10; n /= 10; }
            return r;
        };
        for (int x = 0; x <= num; ++x)
            if ((long long)x + rev(x) == num) return true;
        return false;
    }
};

