class Solution {
    public boolean sumOfNumberAndReverse(int num) {
        if (num == 0) return true;
        int L = String.valueOf(num).length();
        for (int k = 1; k <= L; k++) {
            int h = (k + 1) / 2;
            int start = k > 1 ? (int) Math.pow(10, h - 1) : 0;
            for (int prefix = start; prefix < Math.pow(10, h); prefix++) {
                String p = String.valueOf(prefix);
                StringBuilder sb = new StringBuilder(p);
                if (k % 2 == 0) sb.append(new StringBuilder(p).reverse());
                else sb.append(new StringBuilder(p.substring(0, p.length() - 1)).reverse());
                long cand = Long.parseLong(sb.toString());
                if (cand <= num && cand + rev(cand) == num) return true;
            }
        }
        return false;
    }
    private long rev(long n) {
        long r = 0;
        while (n > 0) { r = r * 10 + n % 10; n /= 10; }
        return r;
    }
}

