var sumOfNumberAndReverse = function(num) {
    if (num === 0) return true;
    const rev = n => Number(String(n).split('').reverse().join(''));
    const L = String(num).length;
    for (let k = 1; k <= L; k++) {
        const h = Math.ceil(k / 2);
        const start = k > 1 ? Math.pow(10, h - 1) : 0;
        for (let prefix = start; prefix < Math.pow(10, h); prefix++) {
            const p = String(prefix);
            const candStr = k % 2 === 0 ? p + [...p].reverse().join('')
                                        : p + [...p].slice(0, -1).reverse().join('');
            const cand = Number(candStr);
            if (cand <= num && cand + rev(cand) === num) return true;
        }
    }
    return false;
};
